def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    # Prepare y in uniform superposition (QFT of |0>).
    for q in range(m):
        qc.h(y[q])

    # Phase kickback: qubit y[q] acquires phase exp(2*pi*i * f / 2^(q+1)).
    L = max(n, m)
    for r in range(L):
        for i in range(n):
            q = (i + r) % L
            if q < m:
                c = S[i] % (2 ** (q + 1))
                if c != 0:
                    qc.cp(pi * c / (2 ** q), x[i], y[q])

    # Decode: semiclassical inverse-QFT-like stage, y[q] ends holding f_q.
    T = 2 * m - 1
    layers = [[] for _ in range(T)]
    for q in range(m):
        layers[2 * q].append(('h', q))
        for j in range(q):
            layers[j + q].append(('cp', j, q))
    for layer in layers:
        for g in layer:
            if g[0] == 'h':
                qc.h(y[g[1]])
            else:
                j, q = g[1], g[2]
                qc.cp(-pi / (2 ** (q - j)), y[j], y[q])

    return qc

from qiskit import QuantumCircuit, QuantumRegister
from math import pi


def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    S = [s % (2 ** m) for s in S]

    # Special case: single input bit -> y = S0 * x0 via CNOT fan-out tree.
    if n == 1:
        targets = [j for j in range(m) if (S[0] >> j) & 1]
        sources = [x[0]]
        remaining = list(targets)
        while remaining:
            new_sources = []
            for src in sources:
                if not remaining:
                    break
                t = remaining.pop(0)
                qc.cx(src, y[t])
                new_sources.append(y[t])
            sources = sources + new_sources
        return qc

    # Special case: single output bit -> parity of x_i with odd S_i.
    if m == 1:
        for i in range(n):
            if S[i] & 1:
                qc.cx(x[i], y[0])
        return qc

    L = max(n, m)
    phase_x = [0.0] * n
    phase_y_pre = [0.0] * m   # diagonal phases applied right after initial H
    phase_y_post = [0.0] * m  # phases on decoded bits (applied at the very end)

    # Accumulate the single-qubit phase parts of every controlled-phase.
    for i in range(n):
        for q in range(m):
            c = S[i] % (2 ** (q + 1))
            if c:
                theta = pi * c / (2 ** q)
                phase_x[i] += theta / 2
                phase_y_pre[q] += theta / 2
    for q in range(m):
        for j in range(q):
            phi = -pi / (2 ** (q - j))
            phase_y_pre[q] += phi / 2
            phase_y_post[j] += phi / 2

    # Prepare y in Fourier basis, and apply all accumulated diagonal phases.
    for q in range(m):
        qc.h(y[q])
        if phase_y_pre[q] != 0.0:
            qc.p(phase_y_pre[q], y[q])

    # Phase kickback: ZZ interactions scheduled so that y_q finishes early for small q.
    for s in range(L):
        for i in range(n):
            q = (s - i) % L
            if q < m:
                c = S[i] % (2 ** (q + 1))
                if c:
                    theta = pi * c / (2 ** q)
                    qc.cx(x[i], y[q])
                    qc.rz(-theta / 2, y[q])
                    qc.cx(x[i], y[q])

    # Semiclassical decode: remove lower-bit contributions, then Hadamard.
    for q in range(m):
        for j in range(q):
            phi = -pi / (2 ** (q - j))
            qc.cx(y[j], y[q])
            qc.rz(-phi / 2, y[q])
            qc.cx(y[j], y[q])
        qc.h(y[q])

    # Remaining diagonal phases (control-side parts of the controlled phases).
    for j in range(m):
        if phase_y_post[j] != 0.0:
            qc.p(phase_y_post[j], y[j])
    for i in range(n):
        if phase_x[i] != 0.0:
            qc.p(phase_x[i], x[i])

    return qc

from qiskit import QuantumCircuit, QuantumRegister
from math import pi


def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    S = [s % (1 << m) for s in S]

    # n == 1: y = S0 * x0 via CNOT fan-out tree
    if n == 1:
        targets = [j for j in range(m) if (S[0] >> j) & 1]
        sources = [x[0]]
        rem = list(targets)
        while rem:
            new = []
            for src in sources:
                if not rem:
                    break
                t = rem.pop(0)
                qc.cx(src, y[t])
                new.append(y[t])
            sources = sources + new
        return qc

    # m == 1: parity of x_i with odd S_i
    if m == 1:
        for i in range(n):
            if S[i] & 1:
                qc.cx(x[i], y[0])
        return qc

    tasks = {}
    pre = [0.0] * m
    post_y = [0.0] * m
    post_x = [0.0] * n

    for q in range(1, m):
        tasks[('INIT', q)] = dict(qubits=[('y', q)], dur=1, deps=[])
    cn_keys = []
    for i in range(n):
        if S[i] & 1:
            tasks[('CN', i)] = dict(qubits=[('x', i), ('y', 0)], dur=1, deps=[])
            cn_keys.append(('CN', i))

    for q in range(1, m):
        for i in range(n):
            c = S[i] % (1 << (q + 1))
            if c:
                theta = pi * c / (1 << q)
                post_x[i] += theta / 2
                pre[q] += theta / 2
                tasks[('KB', i, q)] = dict(qubits=[('x', i), ('y', q)], dur=3,
                                           deps=[('INIT', q)], angle=-theta / 2)
        for j in range(q):
            if j == 0 and not cn_keys:
                continue
            theta = -pi / (1 << (q - j))
            pre[q] += theta / 2
            post_y[j] += theta / 2
            if j >= 1:
                deps = [('INIT', q), ('FIN', j)]
            else:
                deps = [('INIT', q)] + list(cn_keys)
            tasks[('DC', j, q)] = dict(qubits=[('y', j), ('y', q)], dur=3,
                                       deps=deps, angle=-theta / 2)
        fdeps = [('INIT', q)] + [k for k in tasks
                                 if (k[0] == 'KB' and k[2] == q) or (k[0] == 'DC' and k[2] == q)]
        tasks[('FIN', q)] = dict(qubits=[('y', q)], dur=1, deps=fdeps)

    succ = {k: [] for k in tasks}
    for k, t in tasks.items():
        for d in t['deps']:
            succ[d].append(k)
    prio = {}

    def get_prio(k):
        if k in prio:
            return prio[k]
        v = tasks[k]['dur'] + max([get_prio(s) for s in succ[k]] + [0])
        prio[k] = v
        return v

    for k in tasks:
        get_prio(k)

    free = {}
    start = {}
    finish = {}
    unsched = set(tasks.keys())
    while unsched:
        best = None
        for k in unsched:
            t = tasks[k]
            if any(d not in finish for d in t['deps']):
                continue
            est = max([free.get(qb, 0) for qb in t['qubits']] +
                      [finish[d] for d in t['deps']] + [0])
            key = (est, -prio[k])
            if best is None or key < best[0]:
                best = (key, k)
        k = best[1]
        est = best[0][0]
        start[k] = est
        finish[k] = est + tasks[k]['dur']
        for qb in tasks[k]['qubits']:
            free[qb] = finish[k]
        unsched.remove(k)

    order = sorted(tasks.keys(), key=lambda k: start[k])
    for k in order:
        t = tasks[k]
        if k[0] == 'INIT':
            q = k[1]
            qc.u(pi / 2, pre[q], pi, y[q])
        elif k[0] == 'CN':
            i = k[1]
            qc.cx(x[i], y[0])
        elif k[0] == 'KB':
            i, q = k[1], k[2]
            qc.cx(x[i], y[q])
            qc.rz(t['angle'], y[q])
            qc.cx(x[i], y[q])
        elif k[0] == 'DC':
            j, q = k[1], k[2]
            qc.cx(y[j], y[q])
            qc.rz(t['angle'], y[q])
            qc.cx(y[j], y[q])
        elif k[0] == 'FIN':
            q = k[1]
            qc.u(pi / 2, post_y[q], pi, y[q])

    if post_y[0] != 0.0:
        qc.p(post_y[0], y[0])
    for i in range(n):
        if post_x[i] != 0.0:
            qc.p(post_x[i], x[i])

    return qc

from qiskit import QuantumCircuit, QuantumRegister
from math import pi


def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    S = [s % (1 << m) for s in S]
    if all(s == 0 for s in S):
        return qc

    # lowest bit position that can ever be nonzero
    v = min(((s & -s).bit_length() - 1) for s in S if s)
    base = [i for i in range(n) if (S[i] >> v) & 1]
    hi = list(range(v + 1, m))

    # Only one nontrivial output bit: it is a parity.
    if not hi:
        for i in base:
            qc.cx(x[i], y[v])
        return qc

    # Single input bit: y = S0 * x0 via CNOT fan-out tree.
    if n == 1:
        targets = [j for j in range(m) if (S[0] >> j) & 1]
        sources = [x[0]]
        while targets:
            new = []
            for src in sources:
                if not targets:
                    break
                t = targets.pop(0)
                qc.cx(src, y[t])
                new.append(y[t])
            sources = sources + new
        return qc

    def X(i):
        return i

    def Y(q):
        return n + q

    tasks = {}

    def add(key, qubits, deps, gates):
        tasks[key] = dict(qubits=qubits, deps=deps, gates=gates, dur=len(gates))

    pre = [0.0] * m
    post_y = [0.0] * m
    post_x = [0.0] * n
    kb = {}
    dc = {}
    for q in hi:
        kb[q] = []
        for i in range(n):
            c = S[i] % (1 << (q + 1))
            if c:
                th = pi * c / (1 << q)
                kb[q].append((i, th))
                post_x[i] += th / 2
                pre[q] += th / 2
        dc[q] = []
        for j in range(v, q):
            if j == v and not base:
                continue
            ph = -pi / (1 << (q - j))
            dc[q].append((j, ph))
            pre[q] += ph / 2
            post_y[j] += ph / 2

    cn_keys = []
    for i in base:
        k = ('CN', i)
        add(k, [X(i), Y(v)], [], [('cx', X(i), Y(v))])
        cn_keys.append(k)

    for q in hi:
        init_gates = [('h', Y(q))]
        if pre[q] != 0.0:
            init_gates.append(('rz', pre[q], Y(q)))
        add(('INIT', q), [Y(q)], [], init_gates)
        fdeps = [('INIT', q)]
        for (i, th) in kb[q]:
            k = ('KB', i, q)
            add(k, [X(i), Y(q)], [('INIT', q)],
                [('cx', X(i), Y(q)), ('rz', -th / 2, Y(q)), ('cx', X(i), Y(q))])
            fdeps.append(k)
        for (j, ph) in dc[q]:
            k = ('DC', j, q)
            if j == v:
                deps = [('INIT', q)] + list(cn_keys)
            else:
                deps = [('INIT', q), ('FIN', j)]
            add(k, [Y(j), Y(q)], deps,
                [('cx', Y(j), Y(q)), ('rz', -ph / 2, Y(q)), ('cx', Y(j), Y(q))])
            fdeps.append(k)
        add(('FIN', q), [Y(q)], fdeps, [('h', Y(q))])

    # Phases on decoded y bits (applied after they are decoded, order irrelevant).
    for j in range(v, m):
        if post_y[j] != 0.0:
            if j == v:
                deps = list(cn_keys)
            else:
                deps = [('FIN', j)]
            add(('YP', j), [Y(j)], deps, [('rz', post_y[j], Y(j))])
    for i in range(n):
        if post_x[i] != 0.0:
            add(('XP', i), [X(i)], [], [('rz', post_x[i], X(i))])

    # Critical-path priorities.
    succ = {k: [] for k in tasks}
    for k, t in tasks.items():
        for d in t['deps']:
            succ[d].append(k)
    prio = {}

    def pr(k):
        if k not in prio:
            best = 0
            for s in succ[k]:
                best = max(best, pr(s))
            prio[k] = tasks[k]['dur'] + best
        return prio[k]

    for k in tasks:
        pr(k)

    # Time-stepped list scheduling.
    free = {}
    start = {}
    fin = {}
    rem = set(tasks.keys())
    t = 0
    while rem:
        while True:
            cands = []
            for k in rem:
                tk = tasks[k]
                if any(d not in fin for d in tk['deps']):
